pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 rate_, uint256 duration_) internal {
        uint256 i;
        try c.interestFor(0, rate_, duration_) returns (uint256 __r) { i = __r; } catch { return; }
        assertTrue(i == 0);
    }

    function testFuzz_run(uint256 rate_, uint256 duration_) public {
        _run(rate_, duration_);
    }

    receive() external payable {}
}
